CREATE TABLE enterprise_directory_connectors(id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),environment text NOT NULL,app_env text NOT NULL,name text NOT NULL,mode text NOT NULL CHECK(mode IN('scim','synthetic_directory')),owner_id text NOT NULL REFERENCES users(id),config_hash text NOT NULL,enabled integer NOT NULL CHECK(enabled IN(0,1)),version bigint NOT NULL CHECK(version BETWEEN 1 AND 1000000000),updated_at text NOT NULL,PRIMARY KEY(tenant_id,environment,app_env,id));
CREATE TABLE enterprise_directory_users(id text PRIMARY KEY REFERENCES users(id),tenant_id text NOT NULL,environment text NOT NULL,app_env text NOT NULL,connector_id text NOT NULL,user_name text NOT NULL,name_key text NOT NULL,external_id text,display_name text NOT NULL,display_key text NOT NULL,profile_json text NOT NULL CHECK(jsonb_typeof(profile_json::jsonb)='object'),active integer NOT NULL CHECK(active IN(0,1)),deleted integer NOT NULL CHECK(deleted IN(0,1)),review_required integer NOT NULL CHECK(review_required IN(0,1)),directory_version bigint NOT NULL,control_version bigint NOT NULL,policy_hash text NOT NULL,version bigint NOT NULL CHECK(version BETWEEN 1 AND 1000000000),created_at text NOT NULL,updated_at text NOT NULL,FOREIGN KEY(tenant_id,environment,app_env,connector_id) REFERENCES enterprise_directory_connectors(tenant_id,environment,app_env,id),UNIQUE(tenant_id,environment,app_env,connector_id,id));
CREATE UNIQUE INDEX enterprise_directory_user_name ON enterprise_directory_users(tenant_id,environment,app_env,connector_id,name_key) WHERE deleted=0;
CREATE INDEX enterprise_directory_user_external ON enterprise_directory_users(tenant_id,environment,app_env,connector_id,external_id);
CREATE TABLE enterprise_directory_groups(id text PRIMARY KEY,tenant_id text NOT NULL,environment text NOT NULL,app_env text NOT NULL,connector_id text NOT NULL,external_id text,display_name text NOT NULL,display_key text NOT NULL,deleted integer NOT NULL CHECK(deleted IN(0,1)),version bigint NOT NULL CHECK(version BETWEEN 1 AND 1000000000),created_at text NOT NULL,updated_at text NOT NULL,FOREIGN KEY(tenant_id,environment,app_env,connector_id) REFERENCES enterprise_directory_connectors(tenant_id,environment,app_env,id),UNIQUE(tenant_id,environment,app_env,connector_id,id));
CREATE TABLE enterprise_directory_group_members(tenant_id text NOT NULL,environment text NOT NULL,app_env text NOT NULL,connector_id text NOT NULL,group_id text NOT NULL,user_id text NOT NULL,created_at text NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(tenant_id,environment,app_env,connector_id,group_id) REFERENCES enterprise_directory_groups(tenant_id,environment,app_env,connector_id,id),FOREIGN KEY(tenant_id,environment,app_env,connector_id,user_id) REFERENCES enterprise_directory_users(tenant_id,environment,app_env,connector_id,id));
CREATE TABLE enterprise_directory_events(id text PRIMARY KEY,tenant_id text NOT NULL,environment text NOT NULL,app_env text NOT NULL,connector_id text NOT NULL,actor_id text NOT NULL,action text NOT NULL,resource_id text NOT NULL,revision bigint NOT NULL,member_event_id text,created_at text NOT NULL);
CREATE INDEX enterprise_directory_event_scope ON enterprise_directory_events(tenant_id,environment,app_env,connector_id,created_at,id);
CREATE TRIGGER enterprise_directory_events_immutable BEFORE UPDATE OR DELETE ON enterprise_directory_events FOR EACH ROW EXECUTE FUNCTION dg_native_identity_event_immutable();
